#include <stdio.h>
static int frequency[15], best;
static const char *names[] = {"HIGH",     "PAIR", "TWO_PAIR", "THREE",
                              "STRAIGHT", "FULL", "FOUR"};
static void classify(int wild) {
    if (wild) {
        for (int rank = 1; rank <= 13; rank++)
            if (frequency[rank] < 4) {
                frequency[rank]++;
                classify(wild - 1);
                frequency[rank]--;
            }
        return;
    }
    int pairs = 0, maximum = 0, run = 0, straight = 0;
    for (int rank = 1; rank <= 14; rank++) {
        int count = frequency[rank == 14 ? 1 : rank];
        if (rank <= 13) {
            pairs += count == 2;
            if (count > maximum)
                maximum = count;
        }
        run = count ? run + 1 : 0;
        if (run == 5)
            straight = 1;
    }
    int score = maximum == 4            ? 6
                : maximum == 3 && pairs ? 5
                : straight              ? 4
                : maximum == 3          ? 3
                : pairs == 2            ? 2
                : pairs                 ? 1
                                        : 0;
    if (score > best)
        best = score;
}
int main(void) {
    int wild = 0;
    for (int i = 0, rank; i < 5; i++) {
        scanf("%d", &rank);
        if (rank)
            frequency[rank]++;
        else
            wild++;
    }
    classify(wild);
    puts(names[best]);
    return 0;
}

